"""Embedded Ableton-generated blank AudioTrack XML template."""

import base64
import zlib
import xml.etree.ElementTree as ET
from functools import lru_cache

_BLANK_AUDIO_TRACK_XML_B64 = ""


@lru_cache(maxsize=1)
def _blank_audio_track_xml() -> bytes:
    return zlib.decompress(base64.b64decode(_BLANK_AUDIO_TRACK_XML_B64))


def create_blank_audio_track_template() -> ET.Element:
    return ET.fromstring(_blank_audio_track_xml())